import org.junit.Test;
import static org.junit.Assert.*;

public class WordUtils_initials_TriageGen2Test {





















    @Test
    public void testInitials_BufferBoundary() {
        // The buffer is size strLen / 2 + 1. 
        // If str is "a b c d e", len is 9. buf size is 9/2 + 1 = 5.
        // Initials are 'a', 'b', 'c', 'd', 'e' (5 chars).
        char[] delimiters = {' '};
        assertEquals("abcde", WordUtils.initials("a b c d e", delimiters));
    }


}

